import{_ as e,o as t,c as i,a3 as r}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"魔改量化计算器","description":"","frontmatter":{"translationSource":{"title":"魔改量化计算器","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=NdPCAZI5kpmdOZobXpuDCr","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/modified-quantitative-calculator"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/modified-quantitative-calculator"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/modified-quantitative-calculator"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/modified-quantitative-calculator"}]]},"headers":[],"relativePath":"zh/modified-quantitative-calculator.md","filePath":"zh/page-NdPCAZI5kpmdOZobXpuDCr.md"}'),o={name:"zh/modified-quantitative-calculator.md"};function s(p,a,d,l,n,c){return t(),i("div",null,[...a[0]||(a[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="魔改量化计算器" aria-hidden="true"></span><span class="logistics-source-anchor" id="quantitative-calculator-improvements-and-implementation" aria-hidden="true"></span><span class="logistics-source-anchor" id="量化计算器改进点与实现方案" aria-hidden="true"></span><h1 id="魔改量化计算器" tabindex="-1">魔改量化计算器 <a class="header-anchor" href="#魔改量化计算器" aria-label="Permalink to &quot;魔改量化计算器&quot;">​</a></h1><blockquote><p>源页面 ID：<code>NdPCAZI5kpmdOZobXpuDCr</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=NdPCAZI5kpmdOZobXpuDCr" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span id="source-block-pGtU40WJ0lS03XwNlupa3C"></span></p><span class="logistics-source-anchor" id="具体目标" aria-hidden="true"></span><h4 id="具体目标" tabindex="-1">具体目标 <a class="header-anchor" href="#具体目标" aria-label="Permalink to &quot;具体目标&quot;">​</a></h4><p>量化计算器标准功能：输入原料限制，机器限制，可能的配方，最优化目标，输出各配方运行速度（台数），并给出对其的解析显示。</p><p>电力平衡：输入配方中包含发电配方与设备耗电，输入额外需求耗电，求解结果应该产出足够多的电力，同时满足最优解。</p><p>限制污水生产：要求结果污水产量为0。</p><p>限制天有烘炉数量：要求天有烘炉设备数小于某个值。</p><p>超库存传输：自动计算超库存传输什么比较好。</p><p>可以开关保持恒激活：使得激活设备数为整数，允许激活但是不工作。</p><p>无效的环境损耗：例如只有两台提纯在惰气氛围中，那么其效率就只有四台的1/2了，不再能达成原本的配方效率。</p><p>实现串行\\并行功能：实现计算设备串行（交替生产不同产物来减少设备需求）并行（反应池同时生产不同产物减少设备需求）的功能。再进一步，串行混池有利用率上限，并行有白名单限制哪些可以做并行。</p><p>末端产物链路展示分离：可能是指可以点击查看某种末端产物及其原料生产过程链路，忽略（半透明显示）其他链路。</p><p>产线划分：将用于不同产物的原料分开，使其显示更加模块化。</p><p>配方上传功能：希望可以自定义配方。</p><p>固气/液气由用户选：这条需求其实和产线简单化类似，希望能指定特定产线使用的原料只由某种方式产出，但是不影响用于其他产线的该原料的来源。</p><p>萌新向凑整模式：可以自动凑整，例如激活物凑6的倍数，产物凑整数每分钟产出，但是不影响正常计算接近最大值的解。</p><p>UI优化：？这是应该在这里提的吗。</p><p>提供原因解释：解析为什么要选择该方案。</p><p>关于产线与原料，这里列一下武陵适合作为原料的物料：污水、清水、沉积酸、源矿、蓝铁矿\\蓝铁块、赤铜矿\\赤铜块、息壤、重息壤(天有烘炉可以造重息壤这一块)、稳定环境(别问为什么有惰气还要有稳定环境)、壤晶废液、惰气（ jnk 留）</p><p><span id="source-block-ryMw8uNIDorsPZ7aHoogh6"></span></p><span class="logistics-source-anchor" id="抽象痛点与需求分析-抽象这一块" aria-hidden="true"></span><h4 id="抽象痛点与需求分析-抽象这一块" tabindex="-1">抽象痛点与需求分析（抽象这一块） <a class="header-anchor" href="#抽象痛点与需求分析-抽象这一块" aria-label="Permalink to &quot;抽象痛点与需求分析（抽象这一块）&quot;">​</a></h4><details><summary>现在zmd还没那么复杂，等副产物一多，同产物不同配方也变多，感觉就很难用了，要调好久。其实最好是用的人自己拼。我感觉不是混产的问题，应该是副产物的问题。副产物一多，整个结果就会很乱，但我其实并不想关注那一块。然后是同种产物多个配方，也会变很乱。（☢caution☢caution☢）</summary><p>如果在现有网页端量化计算器上，可以点击末端产物高亮甚至分离其过程产物和原料，将副产物丢到一边，会不会好一些。</p></details><details><summary>我们自研的量化计算器是不是可以加点条件 达到什么情况就可以混带省电。这样不就一次算出来了 不用这么费人工队（c）</summary><p>应该是说混反应池，那得先研究明白什么情况可以混，扩反产壤晶中虽然一共八个物品八个格子，但是同样会因为没有特别设计而堵上，而且反应池与扩容反应池还有一些区别也还没搞清</p></details><details><summary>我觉得量化计算器真有很大改进空间了。群里的自研计算器该跟上节奏。因为量化计算器已经算不出这种情况了。（xyIvneu_）</summary><p>？</p></details><details><summary>考虑震荡酸环境做理论极限就更抽象了，量化计算器还不能直接算。这量化计算器要是能输变量就好了。（Orirock）</summary><p>震荡酸环境可以通过写“产出环境的0耗电配方”和“消耗环境的配方”解决，一滴酸提供5s*同时供4机器=20环境，配方耗时与消耗环境数量相同，如果利用率不够，可以改写4机器为3机器</p><p>至于变量，要实现线性约束无法达成的变量求解可能不简单，而可以改写为线性约束的又不需要写成变量</p></details><details><summary>量化计算器应该提供产线组合的上传功能。（xylvneu_）</summary><p>如果是希望将固定速率比例配方链缩减到一个配方（名字带产线），就直接写这个配方到数据文件就好了吧，或者说需要自动缩减？</p></details></div>',1)])])}const m=e(o,[["render",s]]);export{h as __pageData,m as default};
